// @generated by:gauntlet run:godseye-local-orchestration
import { randomUUID } from "node:crypto";
import { CONTROL_API_HEADER, CONTROL_API_VERSION } from "@godseye/contracts";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { createControlClient } from "../packages/control-client/src/index.js";
import { owner, projectInput } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";

describe("owner orchestration HTTP and typed client", () => {
  let f: OwnerAuthFixture;
  let engine: InfrastructureEngine;
  let headers: Headers;
  let app: ReturnType<typeof createApp>;
  beforeEach(async () => {
    f = await ownerAuthFixture();
    headers = (await f.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
    engine = new InfrastructureEngine(f.store);
    app = createApp(
      f.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      f.identity,
      engine.foundation,
      undefined,
      engine,
    );
  });
  afterEach(async () => {
    await f.close();
  });
  async function input() {
    const project = await f.core.createProject(owner, projectInput, randomUUID());
    const environment = project.environments.find((value) => value.kind === "development");
    if (!environment) throw new Error("Missing orchestration HTTP environment");
    return {
      projectId: project.id,
      environmentId: environment.id,
      expectedProjectRevision: project.revision,
      expectedEnvironmentRevision: environment.revision,
      title: "Actual owner clarification",
      maxCostMicros: 0,
      lifetimeSeconds: 300,
      steps: [
        {
          id: "question",
          dependsOn: [],
          kind: "clarification" as const,
          question: "Which variant?",
        },
      ],
    };
  }
  const request = (path: string, body: unknown, customHeaders = headers, key = randomUUID()) =>
    app.request(new URL(`/api/v1/agents/orchestration${path}`, f.origin), {
      method: "POST",
      headers: new Headers([...customHeaders, ["idempotency-key", key]]),
      body: JSON.stringify(body),
    });

  it("T-AC-710 authenticates all orchestration routes before parsing caller bodies", async () => {
    const id = randomUUID();
    for (const [method, path] of [
      ["GET", ""],
      ["POST", "/plans"],
      ["POST", "/proposals"],
      ["GET", `/plans/${id}`],
      ...["approve", "reject", "cancel", "reconcile", "answer"].map((action) => [
        "POST",
        `/plans/${id}/${action}`,
      ]),
    ]) {
      const response = await app.request(new URL(`/api/v1/agents/orchestration${path}`, f.origin), {
        method,
        headers: f.headers(),
        ...(method === "GET" ? {} : { body: "{}" }),
      });
      expect(response.status).toBe(401);
    }
  });

  it("T-AC-710 rejects CSRF, incompatible versions and unknown authority fields without preparing", async () => {
    const body = await input();
    const crossSite = new Headers(headers);
    crossSite.set("origin", "https://untrusted.invalid");
    expect((await request("/plans", body, crossSite)).status).toBe(403);
    const obsolete = new Headers(headers);
    obsolete.set(CONTROL_API_HEADER, "0.0.0");
    const incompatible = await request("/plans", body, obsolete);
    expect(incompatible.status).toBe(422);
    expect(await incompatible.json()).toMatchObject({ error: { code: "UNSUPPORTED_VERSION" } });
    expect((await request("/plans", { ...body, approvedBy: "forged-owner" })).status).toBe(422);
    const actor = await f.identity.actor(headers);
    if (!actor) throw new Error("Missing actual owner actor");
    expect((await engine.orchestration.overview(actor)).plans).toHaveLength(0);
  });

  it("T-AC-710 roundtrips exact owner preparation and approval through the typed client", async () => {
    const client = createControlClient({
      baseUrl: f.origin,
      headers,
      fetch: async (resource, init) =>
        app.request(resource instanceof Request ? resource : String(resource), init),
    });
    const body = await input(),
      key = randomUUID();
    const prepared = await client.prepareOrchestration(body, key);
    expect(await client.prepareOrchestration(body, key)).toEqual(prepared);
    expect((await client.orchestrationDetail(prepared.plan.id)).state).toBe("pending");
    const approved = await client.approveOrchestration(
      prepared.plan.id,
      { expectedHash: prepared.plan.hash },
      randomUUID(),
    );
    expect(approved.state).toBe("approved");
    await engine.orchestration.tick();
    expect((await client.orchestrationDetail(prepared.plan.id)).state).toBe(
      "waiting_clarification",
    );
    expect((await client.orchestrationOverview()).plans).toHaveLength(1);
  });
});
